/** One-sheet dump: stacked tables on Sheet1, title rows allowed.
 *  Canonical named sheets are tried first. This strategy runs when those names
 *  are missing. Missing fields / dates / refs stay blank — never invented.
 */

import ExcelJS from "exceljs";
import { fillCrowFlies, missingPieceIssues, structuralRefusals } from "../validate";
import {
  blankLeague,
  cellText,
  headersMatch,
  readAgeGroups,
  readAssociations,
  readCampuses,
  readCarveOuts,
  readFamilies,
  readFieldTypes,
  readFields,
  readPreferred,
  readSeason,
  readStaff,
  readTeams,
  readTeamsTable,
  readTravel,
} from "../parse";
import type { IntakeAttempt } from "./types";

type RegionKind =
  | "age-groups"
  | "field-types"
  | "fields"
  | "campuses"
  | "associations"
  | "families"
  | "staff"
  | "teams-table"
  | "preferred"
  | "carve-outs"
  | "season-specials";

function rowValues(ws: ExcelJS.Worksheet, r: number, maxCol: number): string[] {
  const out: string[] = [];
  for (let c = 1; c <= maxCol; c++) {
    const t = cellText(ws.getRow(r).getCell(c));
    if (t) out.push(t);
  }
  return out;
}

function rowHas(values: string[], want: string): boolean {
  return values.some((v) => headersMatch(v, want));
}

function classifyRow(values: string[]): RegionKind | null {
  if (!values.length) return null;
  if (rowHas(values, "parent 1 first name") || rowHas(values, "parent 1 last name")) return "families";
  if ((rowHas(values, "center of") || rowHas(values, "assistant of")) && (rowHas(values, "first name") || rowHas(values, "last name"))) {
    return "staff";
  }
  if (rowHas(values, "team") && (rowHas(values, "not at") || rowHas(values, "must use"))) return "carve-outs";
  if (rowHas(values, "team") && (rowHas(values, "bracket") || rowHas(values, "age group"))) return "teams-table";
  if (
    rowHas(values, "age group") &&
    (rowHas(values, "game length") || rowHas(values, "minimum on the field") || rowHas(values, "maximum on the field")) &&
    !rowHas(values, "team")
  ) {
    return "age-groups";
  }
  if (rowHas(values, "field") && (rowHas(values, "campus") || rowHas(values, "parking") || rowHas(values, "available"))) return "fields";
  if ((rowHas(values, "field type") || (rowHas(values, "type") && (rowHas(values, "width") || rowHas(values, "length")))) && !rowHas(values, "campus")) {
    return "field-types";
  }
  if (rowHas(values, "campus") && (rowHas(values, "street") || rowHas(values, "latitude") || rowHas(values, "home association"))) {
    return "campuses";
  }
  if (rowHas(values, "association") && (rowHas(values, "controlled") || rowHas(values, "home campus"))) return "associations";
  if (rowHas(values, "bracket") && rowHas(values, "rank") && rowHas(values, "day")) return "preferred";
  if (rowHas(values, "kind") && rowHas(values, "date")) return "season-specials";
  return null;
}

function sliceSheet(ws: ExcelJS.Worksheet, r1: number, r2: number, name: string): ExcelJS.Worksheet {
  const wb = new ExcelJS.Workbook();
  const out = wb.addWorksheet(name);
  const maxCol = Math.max(ws.columnCount || 0, 20);
  for (let r = r1; r <= r2; r++) {
    for (let c = 1; c <= maxCol; c++) {
      const v = ws.getRow(r).getCell(c).value;
      if (v != null && v !== "") out.getRow(r - r1 + 1).getCell(c).value = v as ExcelJS.CellValue;
    }
  }
  return out;
}

function looksLikeTravelMatrix(ws: ExcelJS.Worksheet): boolean {
  const maxCol = Math.max(ws.columnCount || 0, 12);
  const names: string[] = [];
  for (let c = 2; c <= maxCol; c++) {
    const t = cellText(ws.getRow(1).getCell(c));
    if (t) names.push(t);
  }
  if (names.length < 2) return false;
  const banned = [
    "game length",
    "minimum on the field",
    "maximum on the field",
    "type",
    "campus",
    "parking",
    "first name",
    "last name",
    "age group",
    "bracket",
  ];
  if (names.some((n) => banned.some((b) => headersMatch(n, b)))) return false;
  const rowNames: string[] = [];
  for (let r = 2; r <= names.length + 4; r++) {
    const t = cellText(ws.getRow(r).getCell(1));
    if (t) rowNames.push(t);
  }
  const overlap = names.filter((n) => rowNames.some((r) => r.trim().toLowerCase() === n.trim().toLowerCase()));
  return overlap.length >= 2;
}

function sheetHasSeasonKv(ws: ExcelJS.Worksheet): boolean {
  const maxRow = ws.rowCount || 0;
  for (let r = 1; r <= maxRow; r++) {
    const k = cellText(ws.getRow(r).getCell(1)).trim().toLowerCase();
    if (k === "first playing date" || k === "last playing date" || k === "playing week starts") return true;
  }
  return false;
}

function regionsOn(ws: ExcelJS.Worksheet): { kind: RegionKind; start: number; end: number }[] {
  const maxRow = ws.rowCount || 0;
  const maxCol = Math.max(ws.columnCount || 0, 20);
  const hits: { kind: RegionKind; row: number }[] = [];
  for (let r = 1; r <= maxRow; r++) {
    const kind = classifyRow(rowValues(ws, r, maxCol));
    if (kind) hits.push({ kind, row: r });
  }
  return hits.map((h, i) => {
    const next = hits[i + 1]?.row ?? maxRow + 1;
    let end = next - 1;
    while (end > h.row && isEmptyRow(ws, end, maxCol) && isEmptyRow(ws, end - 1, maxCol)) end -= 1;
    return { kind: h.kind, start: h.row, end };
  });
}

function isEmptyRow(ws: ExcelJS.Worksheet, r: number, maxCol: number): boolean {
  if (r < 1) return true;
  return rowValues(ws, r, maxCol).length === 0;
}

function mergeUnique<T>(into: T[], more: T[], key: (t: T) => string) {
  const seen = new Set(into.map(key));
  for (const item of more) {
    const k = key(item);
    if (!k || seen.has(k)) continue;
    seen.add(k);
    into.push(item);
  }
}

export function tryOneSheetDump(wb: ExcelJS.Workbook, filename = ""): IntakeAttempt {
  const report: string[] = [];
  const league = blankLeague();
  league.sourceName = filename || undefined;
  league.sampleOnly = false;

  for (const ws of wb.worksheets) {
    const regions = regionsOn(ws);
    for (const region of regions) {
      const slice = sliceSheet(ws, region.start, region.end, region.kind);
      if (region.kind === "age-groups") mergeUnique(league.ageGroups, readAgeGroups(slice, report), (a) => a.name.toLowerCase());
      else if (region.kind === "field-types") mergeUnique(league.fieldTypes, readFieldTypes(slice), (t) => t.name.toLowerCase());
      else if (region.kind === "fields") mergeUnique(league.fields, readFields(slice), (f) => f.name.toLowerCase());
      else if (region.kind === "campuses") mergeUnique(league.campuses, readCampuses(slice), (c) => c.name.toLowerCase());
      else if (region.kind === "associations") mergeUnique(league.associations, readAssociations(slice), (a) => a.name.toLowerCase());
      else if (region.kind === "families") league.families.push(...readFamilies(slice));
      else if (region.kind === "staff") mergeUnique(league.staff, readStaff(slice), (s) => `${s.first} ${s.last}`.toLowerCase());
      else if (region.kind === "teams-table") {
        mergeUnique(league.teams, readTeamsTable(slice), (t) => `${t.bracket} ${t.name}`.toLowerCase());
      } else if (region.kind === "preferred") league.preferredSlots.push(...readPreferred(slice));
      else if (region.kind === "carve-outs") league.carveOuts.push(...readCarveOuts(slice));
    }

    if (!league.teams.length) {
      mergeUnique(league.teams, readTeams(ws), (t) => `${t.bracket} ${t.name}`.toLowerCase());
      mergeUnique(league.teams, readTeamsTable(ws), (t) => `${t.bracket} ${t.name}`.toLowerCase());
    }
    if (!league.ageGroups.length) mergeUnique(league.ageGroups, readAgeGroups(ws, report), (a) => a.name.toLowerCase());
    if (!league.fields.length) mergeUnique(league.fields, readFields(ws), (f) => f.name.toLowerCase());
    if (!league.staff.length) mergeUnique(league.staff, readStaff(ws), (s) => `${s.first} ${s.last}`.toLowerCase());
    if (!league.families.length) {
      const fam = readFamilies(ws);
      if (fam.some((f) => f.children.length || f.parents.some((p) => p.coachOf.length))) league.families.push(...fam);
    }
    if (looksLikeTravelMatrix(ws)) {
      const cells = readTravel(ws, league.campuses);
      for (const cell of cells) {
        if (!league.travel.some((t) => t.from === cell.from && t.to === cell.to)) league.travel.push(cell);
      }
    }
    if (!league.season.firstRaw && sheetHasSeasonKv(ws)) {
      const { season, dateIssues } = readSeason(ws);
      league.season = season;
      report.push(...dateIssues.map((i) => i.message));
    }
  }

  const got =
    league.teams.length +
    league.ageGroups.length +
    league.fields.length +
    league.families.length +
    league.staff.length +
    league.campuses.length;
  if (!got) {
    return { matched: false, strategy: "one-sheet-dump", reason: "no soccer-shaped tables" };
  }

  league.travel = fillCrowFlies(league);

  const allStructural = structuralRefusals(league);
  const hard = allStructural.filter((i) => i.code !== "age-group-incomplete" && i.code !== "leftover-sample");
  const soft = allStructural
    .filter((i) => i.code === "age-group-incomplete" || i.code === "leftover-sample")
    .map((i) => ({ ...i, level: "flag" as const }));
  const issues = [...soft, ...missingPieceIssues(league)];
  if (hard.length) {
    return {
      matched: true,
      strategy: "one-sheet-dump",
      result: { ok: false, league, issues: [...issues, ...hard], report, strategy: "one-sheet-dump" },
    };
  }
  return {
    matched: true,
    strategy: "one-sheet-dump",
    result: { ok: true, league, issues, report, strategy: "one-sheet-dump" },
  };
}
